import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64

.shared .align 4 .b8 s_partials[1024];

.visible .entry sdp_attn_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 O_ptr,
    .param .u32 B,
    .param .u32 H,
    .param .u32 S,
    .param .u32 D
)
{
    .reg .pred p_exit, p0, p1, p2, p_tmp;
    .reg .u32 rB, rH, rS, rD;
    .reg .u64 Q, K, V, O;
    .reg .u32 bx, by, bz, tid, bdim;
    .reg .u32 tmp32, row_idx, base_bh, base_bhS;
    .reg .u64 q_row_bytes, o_row_bytes;
    .reg .u64 addr, addr2;
    .reg .f32 q0, q1, q2, q3;
    .reg .f32 part, kval;
    .reg .f32 dot, scale, invln2, neg_inf, maxv, w, delta, denom;
    .reg .f16 htmp;
    .reg .u32 d0, d1, d2, d3;
    .reg .u32 j, stride;
    .reg .u64 sbase;
    .reg .f32 out0, out1, out2, out3;

    ld.param.u64 Q, [Q_ptr];
    ld.param.u64 K, [K_ptr];
    ld.param.u64 V, [V_ptr];
    ld.param.u64 O, [O_ptr];
    ld.param.u32 rB, [B];
    ld.param.u32 rH, [H];
    ld.param.u32 rS, [S];
    ld.param.u32 rD, [D];

    mov.u32 bx, %ctaid.x;
    mov.u32 by, %ctaid.y;
    mov.u32 bz, %ctaid.z;
    mov.u32 tid, %tid.x;
    mov.u32 bdim, %ntid.x;

    setp.ge.u32 p0, bx, rS;
    setp.ge.u32 p1, by, rH;
    setp.ge.u32 p2, bz, rB;
    or.pred p_tmp, p0, p1;
    or.pred p_exit, p_tmp, p2;
    @p_exit bra DONE;

    cvta.to.shared.u64 sbase, s_partials;

    mov.f32 scale, 0.03125;
    mov.f32 invln2, 1.442695;
    mov.f32 neg_inf, -3.402823466e38;

    mad.lo.u32 base_bh, bz, rH, by;
    mul.lo.u32 base_bhS, base_bh, rS;
    add.u32 row_idx, base_bhS, bx;

    mul.wide.u32 addr, row_idx, rD;
    shl.b64 addr, addr, 1;
    add.u64 q_row_bytes, Q, addr;
    add.u64 o_row_bytes, O, addr;

    // Load Q tile into registers
    mov.u32 d0, tid;
    setp.ge.u32 p0, d0, rD;
    @p0 mov.f32 q0, 0.0;
    @!p0 {
        mul.wide.u32 addr2, d0, 2;
        add.u64 addr2, q_row_bytes, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 q0, htmp;
    }

    add.u32 d1, tid, bdim;
    setp.ge.u32 p0, d1, rD;
    @p0 mov.f32 q1, 0.0;
    @!p0 {
        mul.wide.u32 addr2, d1, 2;
        add.u64 addr2, q_row_bytes, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 q1, htmp;
    }

    add.u32 d2, d1, bdim;
    setp.ge.u32 p0, d2, rD;
    @p0 mov.f32 q2, 0.0;
    @!p0 {
        mul.wide.u32 addr2, d2, 2;
        add.u64 addr2, q_row_bytes, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 q2, htmp;
    }

    add.u32 d3, d2, bdim;
    setp.ge.u32 p0, d3, rD;
    @p0 mov.f32 q3, 0.0;
    @!p0 {
        mul.wide.u32 addr2, d3, 2;
        add.u64 addr2, q_row_bytes, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 q3, htmp;
    }

    // Pass 1: max logit
    mov.f32 maxv, neg_inf;
    mov.u32 j, 0;

PASS1_J_LOOP:
    setp.ge.u32 p0, j, rS;
    @p0 bra PASS1_DONE;

    add.u32 tmp32, base_bhS, j;
    mul.wide.u32 addr, tmp32, rD;
    shl.b64 addr, addr, 1;
    add.u64 addr, K, addr;

    mov.f32 part, 0.0;

    setp.ge.u32 p0, d0, rD;
    @p0 bra SKIP_K0;
        mul.wide.u32 addr2, d0, 2;
        add.u64 addr2, addr, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 kval, htmp;
        fma.rn.f32 part, q0, kval, part;
SKIP_K0:

    setp.ge.u32 p0, d1, rD;
    @p0 bra SKIP_K1;
        mul.wide.u32 addr2, d1, 2;
        add.u64 addr2, addr, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 kval, htmp;
        fma.rn.f32 part, q1, kval, part;
SKIP_K1:

    setp.ge.u32 p0, d2, rD;
    @p0 bra SKIP_K2;
        mul.wide.u32 addr2, d2, 2;
        add.u64 addr2, addr, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 kval, htmp;
        fma.rn.f32 part, q2, kval, part;
SKIP_K2:

    setp.ge.u32 p0, d3, rD;
    @p0 bra SKIP_K3;
        mul.wide.u32 addr2, d3, 2;
        add.u64 addr2, addr, addr2;
        ld.global.f16 htmp, [addr2];
        cvt.f32.f16 kval, htmp;
        fma.rn.f32 part, q3, kval, part;
SKIP_K3:

    mul.wide.u32 addr2, tid, 4;
    add.u64 addr2, sbase, addr2;
    st.shared.f32 [addr2], part;

